css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

body { display: flex; align-items: flex-end; min-height: 100vh; margin: 0; }

.bs-tab {
  display: flex; gap: 4px; width: 100%;
  /* Onze destinos não cabem em 375px: em vez de espremer o alvo de toque
     abaixo de 44px, a barra rola na horizontal. */
  overflow-x: auto; scrollbar-width: none;
  height: 84px; padding: 8px 8px 24px;
  border-top: 1px solid var(--border); background: var(--bg-surface);
}
.bs-tab::-webkit-scrollbar { display: none; }

.bs-tab-item {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  flex-shrink: 0; width: 64px;
  border: none; background: transparent; color: var(--text-muted);
  font-family: var(--fonte);
}

.bs-tab-icwrap { position: relative; display: flex; }
.bs-tab-ic { width: 22px; height: 22px; stroke-width: 1.8; }
.bs-tab-rotulo {
  max-width: 100%; font-size: 10px; font-weight: 500;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* Peso e traço mudam junto com a cor: quem não separa o azul do cinza ainda
   enxerga qual aba está aberta. */
.bs-tab-ativo { color: var(--accent); }
.bs-tab-ativo .bs-tab-ic { stroke-width: 2.2; }
.bs-tab-ativo .bs-tab-rotulo { font-weight: 700; }

.bs-tab-badge {
  position: absolute; top: -4px; right: -8px;
  min-width: 16px; padding: 0 4px; border-radius: 999px;
  font-size: 10px; font-weight: 700; line-height: 16px; text-align: center;
  color: var(--bg-base); background: var(--accent);
}

js:
export function iniciarTabBar(raiz) {
  raiz.querySelectorAll('.bs-tab-item').forEach((item) => {
    item.addEventListener('click', () => {
      raiz.querySelectorAll('.bs-tab-item').forEach((i) => {
        i.classList.remove('bs-tab-ativo')
        i.removeAttribute('aria-current')
      })
      item.classList.add('bs-tab-ativo')
      item.setAttribute('aria-current', 'page')
      // Aba escolhida no fim da rolagem some pela metade sem isso.
      item.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' })
    })
  })
}
